wire rgb_hsync_src;
wire rgb_vsync_src;
wire rgb_vde_src;
wire clk_pixel;
wire clk_serial;

//System clock
clk_wiz_0 clk_10(.clk_out1(clk_100MHz_system),.clk_out2(clk_200MHz),.resetn(i_rst),.clk_in1(i_clk));
//HDMI driver
rgb2dvi_0 Mini_HDMI_Driver(
.TMDS_Clk_p(TMDS_Tx_Clk_P),
// output wire TMDS_Clk_p
.TMDS_Clk_n(TMDS_Tx_Clk_N),
// output wire TMDS_Clk_n
