//The three-state node of the SDA line of the camera IIC
wire camera_iic_sda_i;
wire camera_iic_sda_o;
wire camera_iic_sda_t;

//Tri-state gate
IOBUF Camera_IIC_SDA_IOBUF
(.I(camera_iic_sda_o),
.IO(i_camera_iic_sda),
.O(camera_iic_sda_i),
.T(~camera_iic_sda_t));
//Camera IIC drive signal
wire iic_busy;
