1. Edge detection.

Edge detection is an extremely important method of image analysis in image processing and computer vision. Its purpose is to find a
collection of pixels with sharp brightness changes in the image, which often shows contours. If the edge can be accurately measured
and located in the image, it means that the actual object can be located and measured, including the area,diameter and the shape of
the object can be measured. In the image acquisition of the real world, the following situations will form an edge in the image:

(1) Discontinuity in depth. (2) Discontinuity in the surface direction. (3) The material of the object is different. (4)The lighting in the scene
is different. (5)Other circumstances.

As shown in Figure 12-1, we can see the effect of edge detection.

• Check the principle of edge detection and learn about several edge detection operators, such as Sobel operator, Roberts operator,
Preswitt operator, Laplacian operator, Canny operator.

2. Shift register

• Add the RAM-based Shift Register IP core of the shift register, as shown in Fig. 12-2.

• Considering that our image is 720p, there are 1280 data in one line. Therefore, when the shift register stores 2 rows and cannot be
stored at one time, we divide them into 4 blocks, and each block has a data length of 640. The specific parameter settings are shown
in Fig.12-3.

• Shift register description: The input data enters the register and comes out after 640 clock cycles, as shown in Fig. 12-4.

3. Implementation of edge detection

• The image grayscale is implemented by the formula Gray=R*0.3+G*0.59+B*0.11. But for FPGA, such floating-point operations
consume too much resources. Here we optimize the algorithm and go to floating-point operations. Create a new RGB_To_Gray.v file
and enter the following code:
//RGB data to grayscale

module RGB_To_Gray(
input [7:0]i_rgb_data_r,
//Pixel data R
input [7:0]i_rgb_data_g,
//Pixel data G
input [7:0]i_rgb_data_b,
//Pixel data B
input [4:0]i_accuracy_num,
//Grayscale precision digits
output [7:0]o_gray_data
//Output grayscale data
);
//Temporary grayscale data
reg [32:0]gray_data_buff=0;

//Output wiring
assign o_gray_data=gray_data_buff[7:0];

//Gray value calculation
always@(*)
begin
//Different precision digits, 0-20 digits
case(i_accuracy_num)
0:gray_data_buff=(i_rgb_data_r*30+i_rgb_data_b*11+i_rgb_data_g*59+50)/100;
1:gray_data_buff=(i_rgb_data_r*30+i_rgb_data_b*11+i_rgb_data_g*59+50)/100;
2:gray_data_buff=(i_rgb_data_r*1+i_rgb_data_b*1+i_rgb_data_g*2)>>2;
3:gray_data_buff=(i_rgb_data_r*2+i_rgb_data_b*1+i_rgb_data_g*5)>>3;
4:gray_data_buff=(i_rgb_data_r*4+i_rgb_data_b*2+i_rgb_data_g*10)>>4;
5:gray_data_buff=(i_rgb_data_r*9+i_rgb_data_b*4+i_rgb_data_g*19)>>5;
6:gray_data_buff=(i_rgb_data_r*19+i_rgb_data_b*8+i_rgb_data_g*37)>>6;
7:gray_data_buff=(i_rgb_data_r*38+i_rgb_data_b*15+i_rgb_data_g*75)>>7;
8:gray_data_buff=(i_rgb_data_r*76+i_rgb_data_b*30+i_rgb_data_g*150)>>8;
9:gray_data_buff=(i_rgb_data_r*153+i_rgb_data_b*59+i_rgb_data_g*300)>>9;
10:gray_data_buff=(i_rgb_data_r*306+i_rgb_data_b*117+i_rgb_data_g*601)>>10;
11:gray_data_buff=(i_rgb_data_r*612+i_rgb_data_b*234+i_rgb_data_g*1202)>>11;
12:gray_data_buff=(i_rgb_data_r*1224+i_rgb_data_b*467+i_rgb_data_g*2405)>>12;
13:gray_data_buff=(i_rgb_data_r*2449+i_rgb_data_b*934+i_rgb_data_g*4809)>>13;
14:gray_data_buff=(i_rgb_data_r*4898+i_rgb_data_b*1868+i_rgb_data_g*9618)>>14;
15:gray_data_buff=(i_rgb_data_r*9797+i_rgb_data_b*3736+i_rgb_data_g*19235)>>15;
16:gray_data_buff=(i_rgb_data_r*19595+i_rgb_data_b*7472+i_rgb_data_g*38469)>>16;
17:gray_data_buff=(i_rgb_data_r*39190+i_rgb_data_b*14943+i_rgb_data_g*76939)>>17;
18:gray_data_buff=(i_rgb_data_r*78381+i_rgb_data_b*29885+i_rgb_data_g*153878)>>18;
19:gray_data_buff=(i_rgb_data_r*156762+i_rgb_data_b*59769+i_rgb_data_g*307757)>>19;
default:gray_data_buff=(i_rgb_data_r*313524+i_rgb_data_b*119538+i_rgb_data_g*615514)>>20;
endcase
end
endmodule
• Because the edge detection process is not real-time image processing, it will delay several clocks relative to the original data, so it
is necessary to design a delayer. Here is a simple delayer. Create a new Delay_Signal.v file and enter the following code:
//Signal delay

module Delay_Signal(
input i_clk,
//Signal unit clock
input i_rst,
//Reset signal, low reset
input i_signal,
//Delayed input signal
input [2:0]i_delay_num,
//The number of clocks that need to be delayed, no more than 8, can be
cascaded
output o_signal
//Signal output after delay
);

//Signal buffer
reg [7:0]signal_buff=0;
reg [2:0]delay_num_i=0;

//Output wiring
assign o_signal=signal_buff[delay_num_i];

//Input cache
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
signal_buff<=7'd0;
delay_num_i<=3'd0;
end else begin
signal_buff<={signal_buff[6:0],i_signal};
delay_num_i<=i_delay_num;
end
end

endmodule

• The edge detection process can be regarded as the movement process of a 3*3 data matrix. Taking into account the limited on-
board resources, it is impossible to store a complete picture, and the data matrix only needs 3 rows. Here we use the method of storing
3 rows. Create a new Edge_Check.v file and enter the following code:

//Edge detection

module Edge_Check(

input i_clk,
input i_rst,
input i_rgb_vde,
input i_rgb_hsync,
input i_rgb_vsync,
input [7:0]i_gray_data,
input [7:0]i_gray_gate,
output [23:0]o_rgb_data,
output o_rgb_vde,
output o_rgb_hsync,
output o_rgb_vsync
);

//Edge detection delayed clock
parameter Default_Delay_Num=3'd5;

//Shift register output data
wire [7:0]D0;
wire [7:0]D1;
wire [7:0]D2;
wire [7:0]D3;

//Define the edge detection data matrix 3*3, each matrix 8 bits, a total of 3*3*8=72 bits
reg [71:0]Matrix_Edge_Check_Data=0;
wire [7:0]Matrix_00=Matrix_Edge_Check_Data[71:64];
wire [7:0]Matrix_01=Matrix_Edge_Check_Data[63:56];
wire [7:0]Matrix_02=Matrix_Edge_Check_Data[55:48];
wire [7:0]Matrix_10=Matrix_Edge_Check_Data[47:40];
wire [7:0]Matrix_11=Matrix_Edge_Check_Data[39:32];
wire [7:0]Matrix_12=Matrix_Edge_Check_Data[31:24];
wire [7:0]Matrix_20=Matrix_Edge_Check_Data[23:16];
wire [7:0]Matrix_21=Matrix_Edge_Check_Data[15:8];
wire [7:0]Matrix_22=Matrix_Edge_Check_Data[7:0];

//Define the matrix of edge detection to calculate the intermediate value
reg [10:0]Matrix_Cal_X_0=0;
reg [10:0]Matrix_Cal_X_1=0;
reg [10:0]Matrix_Cal_Y_0=0;
reg [10:0]Matrix_Cal_Y_1=0;

//Define the absolute value of the matrix calculation result of edge detection
reg [10:0]Matrix_Res_X=0;
reg [10:0]Matrix_Res_Y=0;
reg [31:0]Matrix_Res_X2=0;
reg [31:0]Matrix_Res_Y2=0;

//Define threshold square cache
reg [15:0]Gate2_i=0;
reg [1:0]rgb_vde_i=0;
reg [1:0]rgb_hsync_i=0;
reg [1:0]rgb_vsync_i=0;
//Binary output
reg [23:0]binary_data=24'd0;

//Output connection, binary output
assign o_rgb_data=binary_data;

//Binary output
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
binary_data<=24'd0;
end else if(Matrix_Res_X2+Matrix_Res_Y2>Gate2_i&o_rgb_vde==1'b1)begin
binary_data<=24'hffffff;
end else begin
binary_data<=24'd0;
end
end
//Square calculation
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
Matrix_Res_X2<=0;
Matrix_Res_Y2<=0;
end else begin
Matrix_Res_X2<=Matrix_Res_X*Matrix_Res_X;
Matrix_Res_Y2<=Matrix_Res_Y*Matrix_Res_Y;
end
end
//Matrix detection result calculation X
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
Matrix_Res_X<=11'd0;
end else if(Matrix_Cal_X_1>Matrix_Cal_X_0)begin
Matrix_Res_X<=(Matrix_Cal_X_1-Matrix_Cal_X_0);
end else begin
Matrix_Res_X<=(Matrix_Cal_X_0-Matrix_Cal_X_1);
end
end
//Matrix detection result calculation Y
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
Matrix_Res_Y<=11'd0;
end else if(Matrix_Cal_Y_1>Matrix_Cal_Y_0)begin
Matrix_Res_Y<=(Matrix_Cal_Y_1-Matrix_Cal_Y_0);
end else begin
Matrix_Res_Y<=(Matrix_Cal_Y_0-Matrix_Cal_Y_1);
end
end
//Matrix calculation
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
Matrix_Cal_X_0<=11'd0;
Matrix_Cal_X_1<=11'd0;
Matrix_Cal_Y_0<=11'd0;
Matrix_Cal_Y_1<=11'd0;
end else begin
Matrix_Cal_X_0<=Matrix_00+(Matrix_01<<1)+Matrix_02;
Matrix_Cal_X_1<=Matrix_20+(Matrix_21<<1)+Matrix_22;
Matrix_Cal_Y_0<=Matrix_00+(Matrix_10<<1)+Matrix_20;
Matrix_Cal_Y_1<=Matrix_02+(Matrix_12<<1)+Matrix_22;
end
end
//Edge detection matrix shift, 3*3
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
Matrix_Edge_Check_Data<=72'd0;
end else if(rgb_vde_i[1]==1'b1)begin

Matrix_Edge_Check_Data<={Matrix_Edge_Check_Data[47:24],Matrix_Edge_Check_Data[23:0],D1,D3,i_gray_data};
end else begin
Matrix_Edge_Check_Data<=Matrix_Edge_Check_Data;
end
end

//rgb_vde signal delay
Delay_Signal Delay_VDE(
.i_clk(i_clk),
//Signal unit clock
.i_rst(i_rst),
//Reset signal, low reset
.i_signal(rgb_vde_i[1]),
//Delayed input signal
.i_delay_num(Default_Delay_Num),
//The number of clocks that need to be delayed, no more
than 8, can be cascaded
.o_signal(o_rgb_vde)
//Signal output after delay
);
//rgb_hsync signal delay
Delay_Signal Delay_HSYNC(
.i_clk(i_clk),
//Signal unit clock
.i_rst(i_rst),
//Reset signal, low reset
.i_signal(rgb_hsync_i[1]),
//Delayed input signal
.i_delay_num(Default_Delay_Num),
//The number of clocks that need to be delayed, no more
than 8, can be cascaded
.o_signal(o_rgb_hsync)
//Signal output after delay
);
//rgb_vsnc signal delay
Delay_Signal Delay_VSYNC(
.i_clk(i_clk),
//Signal unit clock
.i_rst(i_rst),
//Reset signal, low reset
.i_signal(rgb_vsync_i[1]),
//Delayed input signal
.i_delay_num(Default_Delay_Num),
//The number of clocks that need to be delayed, no more
than 8, can be cascaded
.o_signal(o_rgb_vsync)
//Signal output after delay
);
//Since the image data cannot be completely stored and the storage space is insufficient, the shift
register is used, two lines are stored, and one line is processed.
//The maximum value of the shift register is 1088, and our image for one line is 1280, so we create a
new 640 unit shift register and instantiate 4 uses.
//The internal and the first signals of the shift register chain are connected, and the external first
and last signals are respectively: the input is gray scale data, and the output is shift data.
//First Line
Shift_Line Image_Line_Buffer00(
.D(i_gray_data),
// input wire [7 : 0] D
.CLK(i_clk&i_rgb_vde),
// input wire CLK
.Q(D0)
// output wire [7 : 0] Q
);
Shift_Line Image_Line_Buffer01(
.D(D0),
// input wire [7 : 0] D
.CLK(i_clk&i_rgb_vde),
// input wire CLK
.Q(D1)
// output wire [7 : 0] Q
);
//Second Line
Shift_Line Image_Line_Buffer10(
.D(D1),
// input wire [7 : 0] D
.CLK(i_clk&i_rgb_vde),
// input wire CLK
.Q(D2)
// output wire [7 : 0] Q
);
Shift_Line Image_Line_Buffer11(
.D(D2),
// input wire [7 : 0] D
.CLK(i_clk&i_rgb_vde),
// input wire CLK
.Q(D3)
// output wire [7 : 0] Q
);

//Input threshold cache
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
Gate2_i<=0;
rgb_vde_i<=0;
rgb_hsync_i<=0;
rgb_vsync_i<=0;
end else begin
Gate2_i<=i_gray_gate*i_gray_gate;
rgb_vde_i<={rgb_vde_i[0],i_rgb_vde};
end

end
rgb_hsync_i<={rgb_hsync_i[0],i_rgb_hsync};
rgb_vsync_i<={rgb_vsync_i[0],i_rgb_vsync};

Endmodule
