• According to the process of experiment 12, add the IP core to form a path from the camera to the HDMI, and then embed a module in
it, the input is connected to RGB data, and the output is connected to rdb2dvi, the experiment code is as follows:

module
Lab_12( inpu
t i_clk,
input i_rst,
input i_clk_rx_data_n,
input i_clk_rx_data_p,
input [1:0]i_rx_data_n,
input [1:0]i_rx_data_p,
input i_data_n,
input i_data_p,
inout i_camera_iic_sda,
output o_camera_iic_scl,
output o_camera_gpio,
output TMDS_Tx_Clk_N,
output TMDS_Tx_Clk_P,
output [2:0]TMDS_Tx_Data_N,
output [2:0]TMDS_Tx_Data_P
);
//Clock signal
wire clk_100MHz_system;
wire clk_200MHz;

//HDMI signal
wire [23:0]rgb_data_src;
wire rgb_hsync_src;
wire rgb_vsync_src;
wire rgb_vde_src;
wire clk_pixel;
wire clk_serial;

//Image processing signal
wire [23:0]rgb_data;
wire rgb_hsync;
wire rgb_vsync;
wire rgb_vde;

//System clock
