case(oscillo_scale_i)
end
4'd2:addr_rd<=(set_x_i<<1)+oscillo_offset_i;
4'd3:addr_rd<=(set_x_i<<1)+set_x_i+oscillo_offset_i;
4'd4:addr_rd<=(set_x_i<<2)+oscillo_offset_i;
