//Find the maximum function
function [7:0]MAX;
input [7:0]Data_A;
input [7:0]Data_B;
input [7:0]Data_C;
reg [7:0]Max_AB;
begin
Max_AB = Data_A>=Data_B?Data_A:Data_B;
MAX = Max_AB>=Data_C?Max_AB:Data_C;
end
endfunction

//Find the minimum function
function [7:0]MIN;
input [7:0]Data_A;
input [7:0]Data_B;
input [7:0]Data_C;
reg [7:0]Min_AB;
begin
Min_AB = Data_A <= Data_B ? Data_A : Data_B;
MIN = Min_AB <= Data_C ? Min_AB : Data_C;
end
endfunction

