1. Introduction of the SPI protocol

SPI is a synchronous serial communication protocol, which consists of a master device and one or more slave devices. The master
device initiates synchronous communication with the slave device to complete the data exchange. SPI is a high-speed full-duplex
synchronous communication bus. The standard SPI uses only 4 pins and is often used for communication between master devices
and peripherals (such as EEPROM, real-time digital clock, FLASH, digital signal processor, single-chip microcomputer, etc.) . SPI is
based on master-slave communication. The 4 wires of the standard SPI are SS, SCK, MOSI, and MISO.
(1) SS: Slave device chip select enable signal. If the slave device is low-level enable, pull down this pin, the slave device will be selected,
and the host will communicate with the selected slave.
(2) SCK: Clock signal, generated by the host.
(3) MOSI: The channel through which the master sends instructions or data to the slave, the master is the output, and the slave is the
input.
(4) MISO: The channel through which the master reads the status or data of the slave, the master is the input, and the slave is the
output.

The host of SPI communication has 4 modes in the process of reading and writing data sequence, which are expressed by the
combination of CPOL and CPHA.
(1) CPOL: The polarity of the clock. The communication process is divided into idle time and communication time. The idle state of
SCK before and after data transmission is high level, then CPOL is 1, otherwise it is 0.
(2) CPHA: The phase of the clock.
The 4 modes of SPI are as follows, and the specific timing diagram is shown in Fig. 15-1.
(1) Mode 0: CPOL=0, CPHA=0.
(2) Mode 1: CPOL=0, CPHA=1.
(3) Mode 2: CPOL=1, CPHA=0.
(4) Mode 3: CPOL=1, CPHA=1.

1. Design of SPI controller
The specific experiment steps:
• Create a new project Lab_15_1, add resource files Lab_15_1.v and Driver_SPI_Master.v, add IP core clk_division_v0.

• Take SPI master and mode 0 as an example, enter the following code in Driver_SPI_Master.v:

//SPI Host

module Driver_SPI_Master(
input i_clk,
input i_rst,
input i_cpol,
input i_cpha,
input i_mode_data,
input i_spi_wr,
input i_spi_rd,
input i_spi_miso,
input [7:0]i_data,
output [7:0]o_data,
output o_spi_sck,
output o_spi_mosi,
output o_spi_cs,
output o_dc,
output o_spi_rx_ack,
output o_spi_tx_ack
);
//Data
reg [7:0]data_receive=0;
reg spi_sck_0=0;
reg spi_sck_1=0;
reg spi_sck_2=0;
reg spi_sck_3=0;

//Statement
reg [3:0]state_tx=0;
reg [3:0]state_rx=0;

//Flag
reg flg_spi_wr=0;
reg flg_spi_rd=0;

//Cache
reg cpol_i=0;
reg cpha_i=0;
reg mode_data_i=0;
reg [1:0]spi_wr_i=0;
reg [1:0]spi_rd_i=0;
reg spi_miso_i=0;
reg [7:0]data_i=0;

//Output signal
reg [7:0]data_o=0;
reg spi_sck_o=0;
reg spi_mosi_o=0;
reg spi_cs_o=1'b1;
reg spi_dc_o=0;
reg spi_rx_ack_o=0;
reg spi_tx_ack_o=0;

//Output wiring
assign o_spi_sck=spi_sck_o;
assign o_spi_mosi=spi_mosi_o;
assign o_spi_cs=spi_cs_o;
assign o_dc=spi_dc_o;
assign o_spi_rx_ack=spi_rx_ack_o;
assign o_spi_tx_ack=spi_tx_ack_o;
assign o_data=data_o;
always@(*)begin
case({cpol_i,cpha_i})
2'b00:spi_sck_o<=spi_sck_0;
2'b01:spi_sck_o<=spi_sck_1;
2'b10:spi_sck_o<=spi_sck_2;
2'b11:spi_sck_o<=spi_sck_3;
endcase
end

//Clock signal 0
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)spi_sck_0<=1'b0;
else if(flg_spi_wr==1'b1&state_tx[0]==1'b1)spi_sck_0<=1'b1;
else if(flg_spi_rd==1'b1&state_rx[0]==1'b1)spi_sck_0<=1'b1;
else spi_sck_0<=1'b0;
end
//Clock signal 1
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)spi_sck_1<=1'b0;
else if(flg_spi_wr==1'b1&state_tx[0]==1'b0)spi_sck_1<=1'b1;
else if(flg_spi_rd==1'b1&state_rx[0]==1'b0)spi_sck_1<=1'b1;
else spi_sck_1<=1'b0;
end
//Clock signal 2
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)spi_sck_2<=1'b0;
else if(flg_spi_wr==1'b1&state_tx[0]==1'b1)spi_sck_2<=1'b0;
else if(flg_spi_rd==1'b1&state_rx[0]==1'b1)spi_sck_2<=1'b0;
else spi_sck_2<=1'b1;
end
//Clock signal 3
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)spi_sck_3<=1'b0;
else if(flg_spi_wr==1'b1&state_tx[0]==1'b0)spi_sck_3<=1'b0;
else if(flg_spi_rd==1'b1&state_rx[0]==1'b0)spi_sck_3<=1'b0;
else spi_sck_3<=1'b1;
end
//Output chip select signal, dc signal (data or cmd)
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
spi_cs_o<=1'b1;
spi_dc_o<=1'b0;
end else if(flg_spi_wr==1'b1|flg_spi_rd==1'b1|spi_wr_i==2'b01|spi_rd_i==2'b01)begin
spi_cs_o<=1'b0;
spi_dc_o<=mode_data_i;
end else begin
end

end
spi_cs_o<=1'b1;
spi_dc_o<=1'b0;
//Output received data
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)data_o<=8'd0;
else if(spi_rx_ack_o==1'b1)data_o<=data_receive;
else data_o<=data_o;
end
//Output sending status signal
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)spi_tx_ack_o<=1'b0;
else if(state_tx==4'd0)spi_tx_ack_o<=1'b0;
else spi_tx_ack_o<=1'b1;
end
//Output receiving status signal
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)spi_rx_ack_o<=1'b0;
else if(state_rx==4'd0)spi_rx_ack_o<=1'b0;
else spi_rx_ack_o<=1'b1;
end

//send status
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
state_tx<=4'd0;
spi_mosi_o<=1'b0;
end else if(flg_spi_wr==1'b1&state_tx[0]==1'b1)begin
spi_mosi_o<=spi_mosi_o;
state_tx<=state_tx+1;
end else if(flg_spi_wr==1'b1)begin
spi_mosi_o<=data_i[(7-state_tx[3:1])];
state_tx<=state_tx+1;
end else begin
state_tx<=4'd0;
spi_mosi_o<=spi_mosi_o;
end
end

//Receiving status
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
state_rx<=4'd0;
data_receive<=8'd0;
end else if(flg_spi_rd==1'b1&state_rx[0]==1'b1)begin
data_receive[(7-state_rx[3:1])]<=spi_miso_i;
state_rx<=state_rx+1;
end else if(flg_spi_rd==1'b1)begin
data_receive<=data_receive;
state_rx<=state_rx+1;
end else begin
data_receive<=data_receive;
state_rx<=4'd0;
end
end
//Write flag judgment
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)flg_spi_wr<=1'b0;
else if(state_tx==4'd0&spi_wr_i==2'b01)flg_spi_wr<=1'b1;
else if(state_tx==4'd15)flg_spi_wr<=1'b0;
else flg_spi_wr<=flg_spi_wr;
end
//Read flag to judge
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)flg_spi_rd<=1'b0;
else if(state_rx==4'd0&spi_rd_i==2'b01)flg_spi_rd<=1'b1;
else if(state_rx==4'd15)flg_spi_rd<=1'b0;
else flg_spi_rd<=flg_spi_rd;
end
//Input cache
always@(posedge i_clk or negedge i_rst)begin
if(i_rst==1'b0)begin
cpol_i<=1'b0;
cpha_i<=1'b0;
mode_data_i<=1'b0;
spi_wr_i<=2'b00;
spi_rd_i<=2'b00;
spi_miso_i<=1'b0;
data_i<=8'd0;
end else begin
cpol_i<=i_cpol;
cpha_i<=i_cpha;
mode_data_i<=i_mode_data;
spi_wr_i<={spi_wr_i[0],i_spi_wr};
spi_rd_i<={spi_rd_i[0],i_spi_rd};
spi_miso_i<=i_spi_miso;
data_i<=i_data;
end
end
endmodule
